//		Exec(ctx)
func (u *MailJobUpsertBulk) UpdateNewValues() *MailJobUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		for _, b := range u.create.builders {
			if _, exists := b.mutation.ID(); exists {
				s.SetIgnore(mailjob.FieldID)
			}
			if _, exists := b.mutation.ChallengeID(); exists {
				s.SetIgnore(mailjob.FieldChallengeID)
			}
			if _, exists := b.mutation.Provider(); exists {
				s.SetIgnore(mailjob.FieldProvider)
			}
			if _, exists := b.mutation.Generation(); exists {
				s.SetIgnore(mailjob.FieldGeneration)
			}
			if _, exists := b.mutation.Template(); exists {
				s.SetIgnore(mailjob.FieldTemplate)
			}
			if _, exists := b.mutation.ExpiresAt(); exists {
				s.SetIgnore(mailjob.FieldExpiresAt)
			}
			if _, exists := b.mutation.CreatedAt(); exists {
				s.SetIgnore(mailjob.FieldCreatedAt)
			}
		}
	}))
	return u
}

